/// Returns the presentation tone for one optional Tailscale publication state.
fn tailscale_publication_tone(state: &TailscalePublicationState) -> theme::StatusTone {
    match state {
        TailscalePublicationState::Ready { .. } => theme::StatusTone::Ready,
        TailscalePublicationState::Checking => theme::StatusTone::Idle,
        TailscalePublicationState::SetupRequired
        | TailscalePublicationState::NotInstalled
        | TailscalePublicationState::Disconnected
        | TailscalePublicationState::AdministratorRequired => theme::StatusTone::Attention,
        TailscalePublicationState::UnsupportedCli
        | TailscalePublicationState::ExistingConfigurationConflict
        | TailscalePublicationState::Failed => theme::StatusTone::Blocked,
    }
}
